# Logging path that is used as a prefix for log file paths

logging_path = os.getcwd()
InstalledHandlerBuilder = None


def set_logging_path(log_path=''):
    """

    :param log_path:
    :return:
    """
    global logging_path  # pylint: disable=global-statement
    if log_path:
        logging_path = log_path
    else:
        logging_path = os.getcwd()


def get_logging_path():
    """

    :return: logging path
    :rtype: str
    """
    return logging_path


# Active loggers
active_loggers = []

TRACE = 1
RAW_DATA = 4


debug_level = None  # means: inactive


def configure_debug_level():
    """Configure debug_level based on environment variable AL_DEBUG_LEVEL"""
    global debug_level  # pylint: disable=global-statement
    level_name = os.getenv('AL_DEBUG_LEVEL', 'not_found').upper()
    allowed = {'TRACE': TRACE, 'RAW_DATA': RAW_DATA, 'DEBUG': logging.DEBUG}
    if level_name in allowed:
        debug_level = allowed[level_name]


class TracedIn(object):
    """
    Decorator to allow for tracing method/function invocation.
    It sends function name and parameters into logger given as decorator parameter
    sends with loglevel=TRACE
    Decorator is active only when environment variable AL_DEBUG_LEVEL = TRACE
    ex.:
    @TracedIn('messaging.dispatcher')
    def method(self, arg1, arg2):
    """
    def __init__(self, logger_name):  # decorator parameter
        """
        Basic initialization.

        :param logger_name:
        """
        self.logger = logging.getLogger(logger_name)
        self.trace_active = (debug_level == TRACE)

    def __call__(self, decorated_method):
        if not self.trace_active:
            return decorated_method

        method_name = decorated_method.__name__

        def _traced_method(*args, **kwargs):  # parameters of decorated_method
            args_list = [str(arg) for arg in args]
            kwargs_list = ['{}={}'.format(arg, kwargs[arg]) for arg in kwargs]
            param_str = ', '.join(args_list + kwargs_list)
            ret = decorated_method(*args, **kwargs)
            self.logger.log(TRACE, '{}({}) returned: {}'.format(method_name, param_str, ret))
            return ret

        return _traced_method


class TracingLogger(logging.getLoggerClass()):
    """Tracing Logger."""
    def trace(self, msg, *args, **kwargs):
        """
        Log message with TRACE level.

        :param msg: log msg
        :return: None
        """
        self.log(TRACE, msg, *args, **kwargs)


def get_loggers_propagate_values(loggers_names):
    """
    Returns propagate values for given loggers

    :param loggers_names:
    :return: {logger.name: logger.propagate}
    """
    return {logger_name: logging.getLogger(logger_name).propagate for logger_name in loggers_names}


def set_loggers_propagate_values_to_true(logger_names):
    """
    Set propagate values to True for given loggers

    :param logger_names:
    :return: None
    """
    for logger_name in logger_names:
        logging.getLogger(logger_name).propagate = True


def set_loggers_propagate_values(loggers_propagate_values):
    """
    Set propagate values for given loggers

    :param loggers_propagate_values:
    :return: None
    """
    for logger_name, propagate_value in loggers_propagate_values.items():
        logging.getLogger(logger_name).propagate = propagate_value


def propagate(function):
    """
    Decorator to propagate log with severity WARNING or higher

    :param function:
    :return:
    """
    def wrapper(*args, **kwargs):
        """

        :param args:
        :param kwargs:
        :return:
        """
        cur_logger_and_its_parents_names = args[0]._get_logger_names_on_propagation_path()
        loggers_orig_propagate_values = get_loggers_propagate_values(cur_logger_and_its_parents_names)
        set_loggers_propagate_values_to_true(cur_logger_and_its_parents_names)

        function(*args, **kwargs)

        set_loggers_propagate_values(loggers_orig_propagate_values)
    return wrapper


class PropagatingLogger(logging.getLoggerClass()):
    """Logger that propagates infos, warnings, errors, exception and criticals"""

    @propagate
    def info(self, *args, **kwargs):
        """logger.info"""
        super(PropagatingLogger, self).info(*args, **kwargs)

    @propagate
    def warning(self, *args, **kwargs):
        """logger.warning"""
        super(PropagatingLogger, self).warning(*args, **kwargs)

    @propagate
    def error(self, *args, **kwargs):
        """logger.error"""
        super(PropagatingLogger, self).error(*args, **kwargs)

    @propagate
    def critical(self, *args, **kwargs):
        """logger.critical"""
        super(PropagatingLogger, self).critical(*args, **kwargs)

    def _get_logger_names_on_propagation_path(self):
        split_logger_name = self.name.split('.')
        return ['.'.join(split_logger_name[0:i + 1]) for i, name in enumerate(split_logger_name)]


class AbstractLibLogger(TracingLogger, PropagatingLogger):
    """
    Logger for abstract Libs development

    has trace() method
    propagate=True for log-records with severity INFO or higher
    """
    pass  # pylint: disable=unnecessary-pass


logging.setLoggerClass(AbstractLibLogger)
ta_ue_logger = logging.getLogger('ta_ue')


def setup_new_file_handler(logger_name, log_level, log_filename, formatter):
    """
    Set up new file handler for given logger.

    :param logger_name: name of logger to which filelogger is added
    :param log_level: logging level
    :param log_filename: path to log file
    :param formatter: formatter for file logger
    :return:  logging.FileHandler object
    """
    logger = logging.getLogger(logger_name)
    cfh = logging.FileHandler(log_filename, 'w')
    cfh.setLevel(log_level)
    cfh.setFormatter(formatter)
    logger.addHandler(cfh)
    return cfh


def create_logger(name, log_file, log_level=TRACE, log_format="%(asctime)s %(levelname)-10s: |%(message)s", datefmt=None):
    """
    Create Logger with file writer.

    :param name: Logger name
    :param log_file: Path to logfile. This path is added to logging_path variable. Final logfile location is logging_path + log_file
    :param log_level: only log records with equal and greater level will be accepted for storage in log
    :param log_format: layout of log file, default is "%(asctime)s %(levelname)-10s: |%(message)s"
    :return: None
    """
    logger = logging.getLogger(name)
    if name not in active_loggers:
        logger.setLevel(log_level)
        logfile_full_path = os.path.join(logging_path, log_file)
        _prepare_logs_folder(logfile_full_path)
        setup_new_file_handler(logger_name=name,
                               log_level=log_level,
                               log_filename=logfile_full_path,
                               formatter=logging.Formatter(fmt=log_format, datefmt=datefmt))
        append_additional_handlers(logger_name=name)
        active_loggers.append(name)
    return logger


def append_additional_handlers(logger_name):
    """
    Calls InstalledHandlerBuilder on provided logger_name. InstalledHandlerBuilder should deal with logic of creation and attaching handler to
    logger.
    :param logger_name: logger for whom the handler should be attached
    :return:
    """
    if InstalledHandlerBuilder:
        InstalledHandlerBuilder(logger_name)


def install_additional_handlers_builder(builder_function):
    """
    Sets function that is called by append_additional_handlers, should deal with logic of creation and attaching handler to loggers.
    :param builder_function: Callable function that takes logger_name as argument and appends handler to provided logger name.
    :return:
    """
    global InstalledHandlerBuilder
    InstalledHandlerBuilder = builder_function


def configure_config_logger():
    """Configure logger with file storing configuration's log"""
    logger = create_logger(name='al.config',
                           log_file='al.config.log',
                           log_level=TRACE,
                           log_format="%(asctime)s.%(msecs)03d %(levelname)-10s |%(message)s",
                           datefmt="%d %H:%M:%S")
    logger.propagate = False


