def mark_tc_phase(msg, additional_loggers=None):
    """
    Put TestCase related marker into all logs requiring that info

    :param msg: TC related message (should show TC phase)
    :param additional_loggers: list of additional logger names
    :return: None
    """
    loggers_needing_tc_info = ['al.config', 'al.aliases', 'al.scopes', 'al.devicepool']
    if additional_loggers:
        loggers_needing_tc_info.extend(additional_loggers)
    for logger_name in loggers_needing_tc_info:
        logger = logging.getLogger(logger_name)
        logger.info(msg=msg)


def _prepare_logs_folder(logfile_full_path):
    """
    Check that log folder exist and creates it if needed.

    :param logfile_full_path: path to log folder
    :return: Nome
    """
    logdir = os.path.dirname(logfile_full_path)
    if not os.path.exists(logdir):
        os.makedirs(logdir)


def close_logger(name):
    """
    Close log handlers for given logger.

    :param name: name of logger
    :return:
    """
    logger = logging.getLogger(name)
    logger.debug('Log handlers closed by ta_ue.logger.close_logger')
    hndlrs = list(logger.handlers)
    for lh in hndlrs:
        try:
            lh.flush()
        except Exception as exc:  # pylint: disable=broad-except
            exception(str(exc))
        logger.removeHandler(lh)
        lh.close()
    if name in active_loggers:
        active_loggers.remove(name)


def setup_logging_from_yaml_config(conf_file=None):
    """
    Setup logging configuration from yaml file.

    Configuration file path is read either in conf_file or
    from environment variable TA_UE_LOG_CONFIG

    :param conf_file: Path to log config file. If given this will override the path in environment variable
    :return: None
    """
    if conf_file:
        path = conf_file
    elif os.getenv('TA_UE_LOG_CONFIG', None):
        path = os.getenv('TA_UE_LOG_CONFIG', None)
    else:
        raise IOError('Path to Log Config File not defined')

    if os.path.isfile(path):
        with open(path, 'rt') as f:
            config = yaml.safe_load(f.read())
        logging.config.dictConfig(config)
    else:
        raise IOError('Log Config File {} Does not exist'.format(path))


# @atexit.register
def close_all_loggers():
    """
    Close log handlers from all created loggers,
    registered to atexit to be called at exit.
    """
    if active_loggers:
        for logger in active_loggers:
            close_logger(logger)


